const en=document.documentElement.lang==='en',t=(zh,eng)=>en?eng:zh,$=s=>document.querySelector(s),name=p=>en?p.name:p.zh,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',room:'<rect x="5" y="3" width="14" height="19" rx="2"/><path d="M9 8h6M9 12h6M15 17h.1"/>',toilet:'<circle cx="8" cy="4" r="1.5"/><circle cx="17" cy="4" r="1.5"/><path d="M5 9h6l1 6H4l1-6Zm1 6v6m4-6v6m5-12h4v7h-4V9Zm1 7v5m2-5v5"/>',saved:'<path d="M6 3h12v19l-6-4-6 4V3Z"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',locate:'<circle cx="12" cy="12" r="6"/><path d="M12 1v5m0 12v5M1 12h5m12 0h5"/>',check:'<path d="m5 12 5 5L20 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-11v1"/>'};
