document.title=t('GreenGo · 校园地点查找','GreenGo · Campus Find');
$('#app').innerHTML=`<header class="topbar"><a class="brand" href="#/find"><img src="assets/mark.svg" alt=""><span>GreenGo<span class="brand-sub">CAMPUS FIND</span></span></a><nav aria-label="${t('主导航','Main navigation')}"><a href="#/find" data-nav="find">${t('发现地点','Find a place')}</a><a href="#/saved" data-nav="saved">${t('已收藏','Saved')}</a><a href="#/about" data-nav="about">${t('关于原型','About')}</a></nav><div class="header-meta"><span class="university">UNIVERSITY OF BIRMINGHAM</span><a class="language" href="${en?'index.html':'en.html'}">${en?'中文':'EN'} ↗</a></div></header><main id="main"><div id="workspace" class="workspace"><section class="discovery" aria-label="${t('地点搜索与详情','Place search and details')}"><div id="discoveryTop"><p class="eyebrow">SMALL PLACES. BIG DIFFERENCE.</p><h1>${t('找到地方，<br>少走弯路。','Little places.<br>Less searching.')}</h1><p class="intro">${t('从教学楼，找到那一间教室。<br>从所在处，找到附近的厕所。','The room inside the building.<br>The facilities around the corner.')}</p></div><div id="searchArea"><form id="searchForm" class="searchbox" role="search">${icon('search')}<label class="sr-only" for="search">${t('搜索教室、房间号码或建筑','Search rooms, room codes or buildings')}</label><input id="search" type="search" autocomplete="off" placeholder="${t('试试 ARTS 127、404、厕所…','Try ARTS 127, 404, toilets…')}"><button class="search-go" type="submit" aria-label="${t('搜索','Search')}">${icon('arrow')}</button></form><div class="categories" aria-label="${t('地点类型','Place type')}"><button data-category="all">${t('全部','All places')}</button><button data-category="room">${icon('room')}${t('找教室','Rooms')}</button><button data-category="toilet">${icon('toilet')}${t('附近厕所','Toilets')}</button></div><div id="facilityFilters" class="filters" hidden><label><input type="checkbox" id="accessible">${t('有无障碍设施资料','Adapted toilet listed')}</label><label><input type="checkbox" id="neutral">${t('性别中立','Gender-neutral')}</label></div><div class="origin-line"><span>${icon('locate')}<span id="originLabel"></span></span><button id="changeOrigin" class="text-button">${t('更改位置','Change')}</button></div></div><div id="resultsHeader" class="results-header"></div><div id="results"></div><div id="detail" hidden></div><div id="guide" hidden></div><p class="directory-note" id="directoryNote">${t('小范围试用目录 · 10 栋建筑 / 14 个地点。厕所目前覆盖主图书馆与 TLB。','Pilot directory · 10 buildings / 14 places. Toilets currently cover Main Library and TLB.')}</p></section><section class="map-panel" aria-label="${t('校园交互地图','Interactive campus map')}"><div class="map-heading"><div><span class="live-dot"></span>EDGBASTON CAMPUS</div><span>${t('建筑位置视图','Building locator')}</span></div><div class="map-viewport"><svg id="campusMap" viewBox="930 435 690 610" role="group" aria-label="${t('可拖动缩放的校园建筑地图；可通过下方按钮选择位置','Pannable campus building map; position can also be selected with the buttons below')}"><image href="assets/campus-map.webp" x="0" y="0" width="1786" height="1263"/><g id="markers"></g><g id="originMarker"></g></svg><div class="map-controls"><button id="zoomIn" aria-label="${t('放大地图','Zoom in')}">＋</button><button id="zoomOut" aria-label="${t('缩小地图','Zoom out')}">−</button><button id="resetMap" aria-label="${t('重置地图','Reset map')}">⌖</button></div><div class="map-key"><span class="key-pin"></span>${t('建筑点位，不是室内门位','Building points, not room doors')}<span class="key-origin"></span>${t('参考起点','Reference origin')}</div><div id="mapHint" class="map-hint" hidden></div></div><div class="map-bottom"><div class="map-note"><strong>${t('先找到楼，再找到房间。','Find the building. Then the room.')}</strong><p>${t('继承提供的 Edgbaston Campus Map；建筑点位与距离均为近似值。','Based on the supplied Edgbaston Campus Map; building points and distances are approximate.')}</p></div><button id="mapPick" class="outline">${icon('pin')}${t('在地图选起点','Set origin on map')}</button></div><div id="contextCard" class="context-card">${icon('room')}<div><strong>${t('房间号不一定等于楼层。','A room number is not a floor.')}</strong><p>${t('楼层有来源才显示；未知地点保留“待核实”。','Floors appear only with a source. Unknown floors stay unconfirmed.')}</p></div><button id="exampleRoom" class="round-arrow" aria-label="${t('查看有楼层资料的教室','View a room with floor information')}">${icon('arrow')}</button></div></section></div><section id="about" class="about-page" hidden></section></main><div id="notice" class="toast" role="status" aria-live="polite" hidden></div><dialog id="locationDialog" aria-labelledby="locationTitle"><div class="dialog-head"><h2 id="locationTitle">${t('从哪里开始找？','Where are you starting?')}</h2><button data-close="locationDialog" class="icon-button" aria-label="${t('关闭','Close')}">${icon('close')}</button></div><p>${t('选择建筑、在地图上选点，或主动授权获取一次位置。位置仅保留于当前页面。','Choose a building, pick a map point or allow a one-time location request. Location stays in this page’s memory.')}</p><label class="field">${t('附近的建筑','Nearby building')}<select id="originBuilding">${buildings.map(b=>`<option value="${b.id}">${esc(b.id+' · '+name(b))}</option>`).join('')}</select></label><button id="useBuilding" class="primary full">${t('使用这个参考起点','Use this reference origin')}</button><div class="dialog-divider">${t('或者','or')}</div><button id="useGPS" class="outline full">${icon('locate')}${t('获取一次当前位置','Use my location once')}</button><p class="small">${t('GPS 可用于校园内的粗略距离比较，不能判断楼层。不会开启后台追踪。','GPS supports approximate campus distance comparison, not floor detection. Background tracking is not enabled.')}</p><button id="clearLocation" class="text-button">${t('清除位置，暂不排序','Clear location and stop ranking')}</button><p id="locationError" class="inline-status" role="status"></p></dialog><dialog id="reportDialog" aria-labelledby="reportTitle"><div class="dialog-head"><h2 id="reportTitle">${t('记录地点问题','Record a place issue')}</h2><button data-close="reportDialog" class="icon-button" aria-label="${t('关闭','Close')}">${icon('close')}</button></div><p id="reportPlace"></p><label class="field">${t('问题类型','Issue type')}<select id="issueType"><option value="floor">${t('楼层或位置不准确','Incorrect floor or location')}</option><option value="access">${t('无法进入或设施关闭','Access problem or closure')}</option><option value="missing">${t('缺少信息','Missing information')}</option></select></label><label class="field">${t('现场观察（不要填写个人信息）','Observation (omit personal information)')}<textarea id="issueNote" rows="4" maxlength="800"></textarea></label><button id="downloadReport" class="primary full">${t('下载反馈记录','Download feedback note')}</button><p class="small">${t('反馈保存为本地文件，尚未提交给学校或小组。','Downloads a local file; nothing is sent to the university or group.')}</p></dialog><dialog id="assistDialog" aria-labelledby="assistTitle"><div class="dialog-head"><h2 id="assistTitle">${t('让到楼提醒更及时','Get a timely arrival prompt')}</h2><button data-close="assistDialog" class="icon-button" aria-label="${t('关闭','Close')}">${icon('close')}</button></div><p>${t('仅在当前页面打开、引导未结束时持续读取位置。接近目标建筑时提示核对楼层，不自动判断已进入教室。位置不上传、不保存。可以随时停止。','While this page is open and guidance is active, check location to prompt a floor check near the destination building. This does not detect room arrival. Location is neither uploaded nor stored. Stop at any time.')}</p><button id="consentAssist" class="primary full">${t('同意并开启到楼提醒','Allow arrival prompts')}</button><button id="manualAssist" class="outline full">${t('改用手动到楼确认','Use manual building check-in')}</button></dialog><aside id="arrivalPrompt" class="arrival-prompt" aria-live="polite" hidden></aside>`;
const mobileMap=document.createElement('button');mobileMap.className='mobile-map-toggle';mobileMap.id='mobileMapToggle';mobileMap.textContent=t('地图视图','Map view');$('.header-meta').prepend(mobileMap);mobileMap.onclick=()=>{const mapOnly=$('#workspace').classList.toggle('map-only');mobileMap.textContent=mapOnly?t('列表视图','List view'):t('地图视图','Map view');};
const svg=$('#campusMap');let box=[930,435,690,610],gesture=null,pointers=new Map(),pinch=null,moved=false;
function setBox(){svg.setAttribute('viewBox',box.join(' '));}
function zoom(f){const w=Math.max(220,Math.min(1600,box[2]*f)),h=w*610/690;box=[box[0]+(box[2]-w)/2,box[1]+(box[3]-h)/2,w,h];setBox();}
$('#zoomIn').onclick=()=>zoom(.78);$('#zoomOut').onclick=()=>zoom(1.28);$('#resetMap').onclick=()=>{box=[930,435,690,610];setBox();};
svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.12:.89);},{passive:false});
svg.onpointerdown=e=>{if(e.button!==0)return;pointers.set(e.pointerId,[e.clientX,e.clientY]);svg.setPointerCapture(e.pointerId);gesture=[e.clientX,e.clientY];moved=false;};
svg.onpointermove=e=>{if(!pointers.has(e.pointerId))return;const old=pointers.get(e.pointerId);pointers.set(e.pointerId,[e.clientX,e.clientY]);if(Math.hypot(e.clientX-old[0],e.clientY-old[1])>2)moved=true;if(pointers.size===2){const a=[...pointers.values()],d=Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]);if(pinch)zoom(pinch/d);pinch=d;gesture=null;}else if(gesture){const rect=svg.getBoundingClientRect(),scale=Math.max(box[2]/rect.width,box[3]/rect.height);box[0]-=(e.clientX-gesture[0])*scale;box[1]-=(e.clientY-gesture[1])*scale;gesture=[e.clientX,e.clientY];setBox();}};
svg.onpointerup=e=>{pointers.delete(e.pointerId);gesture=null;pinch=null;if(moved)return;const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const p=point.matrixTransform(svg.getScreenCTM().inverse());if(state.pick){const geo=mapToGeo(p);if(!inCampus(geo)){toast(t('请选择主校园范围内的位置。','Choose a point within the main campus.'));return;}state.origin={...geo,x:p.x,y:p.y,mode:'map',name:t('地图参考点','Map reference point')};state.accuracy=0;state.pick=false;render();return;}const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-building]');if(target)showBuilding(target.dataset.building);};
svg.onpointercancel=e=>{pointers.delete(e.pointerId);gesture=null;pinch=null;};
function renderMap(){const active=state.selected?bOf(state.selected).id:null;$('#markers').innerHTML=buildings.map(b=>{const wc=places.some(p=>p.building===b.id&&p.type==='toilet');let short=b.name.replace('Teaching and Learning Building','Teaching & Learning').replace(' Building','').replace('Aston Webb – Great Hall','Aston Webb');return `<g class="map-pin ${active===b.id?'selected':''}" data-building="${b.id}" role="button" tabindex="0" aria-label="${esc(t('查看','View')+' '+b.name)}" transform="translate(${b.x} ${b.y})"><circle r="${active===b.id?11:7}"/><rect x="12" y="-17" width="${Math.min(240,short.length*6.3+51)}" height="27" rx="8"/><text x="20" y="1">${b.id} · ${esc(short)}${wc?' · WC':''}</text></g>`;}).join('');$('#markers').querySelectorAll('g').forEach(g=>g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showBuilding(g.dataset.building);}});const o=state.origin,p=o&&(o.x!==undefined?o:geoToMap(o));$('#originMarker').innerHTML=p?`<g transform="translate(${p.x} ${p.y})"><circle class="origin-halo" r="18"/><circle class="origin-dot" r="7"/></g>`:'';$('#mapHint').hidden=!state.pick;$('#mapHint').textContent=t('点击地图设置参考起点 · 可继续拖动或缩放','Tap to set a reference origin · dragging and zooming still work');$('#mapPick').classList.toggle('active',state.pick);}
function originLabel(){const o=state.origin;if(!o)return t('未设置起点','No origin selected');if(o.mode==='gps')return t('当前位置','Device location')+` · ±${Math.round(state.accuracy)}m`;return (o.mode==='example'?t('示例起点：','Example: '):'')+(o.mode==='map'?o.name:name(o));}
function results(){return findPlaces(places,buildings,{...state,saved:state.view==='saved'?saved:null});}
function distanceLabel(p){return p.metres===null?'':p.metres<35?t('同一建筑附近','At this building'):t('约 ','~')+Math.round(p.metres/10)*10+' m';}
function render(){const detail=!!state.selected,guide=!!state.guide;$('#searchArea').hidden=detail||guide;$('#results').hidden=detail||guide;$('#resultsHeader').hidden=detail||guide;$('#directoryNote').hidden=detail||guide;$('#detail').hidden=!detail||guide;$('#guide').hidden=!guide;$('#discoveryTop').hidden=detail||guide;$('#originLabel').textContent=originLabel();$('#facilityFilters').hidden=state.category!=='toilet';document.querySelectorAll('[data-category]').forEach(el=>{el.classList.toggle('active',el.dataset.category===state.category);el.setAttribute('aria-pressed',el.dataset.category===state.category);});document.querySelectorAll('[data-nav]').forEach(a=>a.setAttribute('aria-current',a.dataset.nav===state.view?'page':'false'));
 if(!detail&&!guide){const list=results();$('#resultsHeader').innerHTML=`<h2>${state.view==='saved'?t('常去的小地点','Your little places'):state.category==='toilet'?t('附近的已收录厕所','Nearby listed toilets'):t('地点目录','Places to discover')} <span>${list.length}</span></h2><p>${state.origin?t('按到建筑的近似直线距离排序；不是实际步行距离。','Sorted by approximate straight-line distance to buildings, not walking distance.'):t('设置起点后可按近远排序。','Set an origin to rank nearby buildings.')}</p>`;$('#results').innerHTML=list.length?list.map(p=>`<button class="place-card" data-place="${p.id}"><span class="place-icon ${p.type}">${icon(p.type)}</span><span class="place-copy"><span class="place-kicker">${esc(p.building+' · '+name(bOf(p)))}</span><strong>${esc(name(p))}</strong><span class="card-meta">${floorText(p)}<span>${esc(distanceLabel(p))}</span></span></span><span class="card-arrow">↗</span></button>`).join(''):`<div class="empty">${icon('search')}<h3>${t('暂时没有匹配的地点','No matching places yet')}</h3><p>${t('目录正在逐步完善。试试建筑名或更短的房间号码，或清除筛选。','This is a growing directory. Try a building name or shorter room code, or clear the filters.')}</p><button id="clearFilters" class="outline">${t('清除筛选','Clear filters')}</button></div>`;$('#clearFilters')?.addEventListener('click',()=>{state.query='';state.category='all';state.accessible=false;state.neutral=false;$('#search').value='';$('#accessible').checked=false;$('#neutral').checked=false;render();});$('#results').querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>openPlace(b.dataset.place));}
 if(detail&&!guide)renderDetail();if(guide)renderGuide();renderMap();}
function openPlace(id){const p=places.find(p=>p.id===id);if(!p)return;$('#workspace').classList.remove('map-only');mobileMap.textContent=t('地图视图','Map view');state.selected=p;location.hash='/place/'+id;render();$('.discovery').scrollTop=0;}
function showBuilding(id){if(state.guide){toast(t('请先结束当前引导，再选择其他地点。','Finish the current guidance before selecting another place.'));return;}$('#workspace').classList.remove('map-only');mobileMap.textContent=t('地图视图','Map view');state.selected=null;state.query=id;state.category='all';state.accessible=false;state.neutral=false;$('#search').value=id;$('#accessible').checked=false;$('#neutral').checked=false;location.hash='/find';render();}
function renderDetail(){const p=state.selected,b=bOf(p);$('#detail').innerHTML=`<button class="back text-button" id="backResults">← ${t('返回地点','Back to places')}</button><div class="detail-top"><span class="place-icon large ${p.type}">${icon(p.type)}</span><button id="savePlace" class="save-button ${saved.includes(p.id)?'saved':''}" aria-pressed="${saved.includes(p.id)}">${icon('saved')}${saved.includes(p.id)?t('已收藏','Saved'):t('收藏','Save')}</button></div><p class="eyebrow">${esc(p.building+' / '+b.name)}</p><h1 class="place-title">${esc(name(p))}</h1><div class="detail-badges">${badge(p)}</div><div class="floor-hero"><span>${t('所在楼层','FIND IT ON')}</span><strong>${esc(floor(p))}</strong><p>${p.floor===null?t('不根据房间号码推测楼层。请先核实，再前往。','We do not guess floors from room numbers. Confirm before heading upstairs.'):t('沿用英国楼层名称 · G 为地面层','UK floor labels · G means ground floor')}</p></div><p class="place-note">${esc(p.note[en?1:0])}</p><div class="detail-facts"><div><span>${t('距参考起点','FROM REFERENCE ORIGIN')}</span><strong>${esc(distanceLabel({metres:state.origin&&inCampus(state.origin)?distance(state.origin,b):null})||t('未设置','Not set'))}</strong><small>${t('到建筑的近似直线距离','Approximate straight-line distance to building')}</small></div><div><span>${t('当前使用状态','CURRENT AVAILABILITY')}</span><strong>${t('尚未确认','Not confirmed')}</strong><small>${t('未接入开放、占用或临时关闭状态','No live opening, occupancy or closure feed')}</small></div></div>${p.type==='toilet'?`<div class="facility-tags">${p.accessible?`<span>♿ ${t('来源列有无障碍设施','Adapted facilities listed')}</span>`:''}${p.genderNeutral?`<span>${t('性别中立','Gender-neutral')}</span>`:''}</div>`:''}<button id="startGuide" class="primary full">${t('开始地点引导','Guide me to this place')}${icon('arrow')}</button><button id="reportIssue" class="outline full">${t('信息有误 / 补充线索','Report an issue / add a clue')}</button><details class="source-details"><summary>${t('数据来源与待核实项','Sources & what needs checking')}</summary><p>${p.source?`${t('查阅日期','Consulted')} ${checked} · <a href="${sources[p.source].url}" target="_blank" rel="noopener">${sources[p.source].name} ↗</a>`:t('此地点标签来自前期原型，未取得独立目录验证。','This label comes from the earlier prototype and lacks independent directory verification.')}</p><p>${t('建筑点位为近似位置，未定位到房间门口。楼层未现场复核；请按现场标识与开放情况确认。','Building points are approximate, not room-door coordinates. Floors have not been field-checked; confirm signs and access on site.')}</p></details>`;
 $('#backResults').onclick=()=>{state.selected=null;location.hash='/'+state.view;render();};$('#savePlace').onclick=()=>{saved=saved.includes(p.id)?saved.filter(id=>id!==p.id):[...saved,p.id];try{localStorage.setItem('campus-find:saved',JSON.stringify(saved));}catch{toast(t('此浏览器无法持久保存，收藏仅在当前页面有效。','Storage unavailable; saved places last for this page only.'));}renderDetail();};$('#startGuide').onclick=()=>{state.guide=p;state.stage=0;state.prompted=false;state.muted=false;state.snooze=0;location.hash='/guide/'+p.id;render();};$('#reportIssue').onclick=()=>{$('#reportPlace').textContent=b.name+' · '+p.name;$('#issueNote').value='';$('#reportDialog').showModal();};}
function stopWatch(){if(state.watch!==null){navigator.geolocation?.clearWatch(state.watch);state.watch=null;}}
function renderGuide(){const p=state.guide,b=bOf(p);$('#guide').innerHTML=`<div class="guide-header"><span class="eyebrow">${t('地点引导','PLACE GUIDANCE')}</span><button id="endGuide" class="text-button">${t('结束','End')}</button></div><h1 class="place-title">${esc(name(p))}</h1><p class="intro">${esc(b.name)} · ${esc(floor(p))}</p><div class="stepper" aria-label="${t('引导进度','Guidance progress')}">${[t('找到楼','Building'),t('找楼层','Floor'),t('找地点','Place')].map((v,i)=>`<span class="${state.stage===i?'current':state.stage>i?'done':''}"><b>${state.stage>i?'✓':i+1}</b>${v}</span>`).join('')}</div>${state.stage===0?`<div class="guidance-card"><span class="step-no">01</span><h2>${t('先到这栋建筑','Start with the building')}</h2><p>${esc(b.id+' · '+name(b))}</p><p class="small">${t('地图高亮显示建筑位置。此处不绘制未经验证的步行路线。','The map highlights the building. Unverified walking paths are not drawn.')}</p><a class="outline full" target="_blank" rel="noopener" href="${sources.map.url}">${t('查看大学官方校园地图','Open the university campus map')} ↗</a><button id="arrivedBuilding" class="primary full">${t('已到建筑 / 手动确认','At the building / manual check-in')}</button></div><div class="assist-card">${icon('locate')}<div><strong>${t('到楼时，提醒核对楼层','A floor reminder on approach')}</strong><p>${t('自愿开启，仅在页面打开时运行。','Optional; works only while this page is open.')}</p></div><button id="toggleAssist" class="text-button">${state.watch!==null?t('停止','Stop'):t('开启','Enable')}</button></div>`:state.stage===1?`<div class="guidance-card"><span class="step-no">02</span><h2>${p.floor===null?t('先确认楼层','Confirm the floor first'):t('看楼层，再找房间','Check the floor before the room')}</h2><div class="floor-hero compact"><span>${t('目标楼层','DESTINATION FLOOR')}</span><strong>${esc(floor(p))}</strong></div><p>${p.floor===null?t('资料不足。请查建筑内目录、现场指示或向工作人员询问；不会生成猜测的楼层和转向。','Information is incomplete. Check the building directory, signs or staff. Floors and turns are not invented.'):t('楼层信息来自链接资料，未现场复核。使用现场标识找到对应楼层；需要电梯时先核对通行情况。','The linked source supplies the floor; it has not been field-checked. Follow on-site labels and check lift access if needed.')}</p>${p.source?`<a class="outline full" href="${sources[p.source].url}" target="_blank" rel="noopener">${t('查看地点来源','Open place source')} ↗</a>`:''}<button id="floorChecked" class="primary full">${p.floor===null?t('已向现场确认楼层','Floor confirmed on site'):t('已到对应楼层','At the indicated floor')}</button><button id="previousStage" class="text-button">← ${t('回到建筑步骤','Back to building')}</button></div>`:`<div class="guidance-card"><span class="step-no">03</span><h2>${t('核对门牌，找到地点','Check the sign. Find the place.')}</h2><div class="destination-ticket">${icon(p.type)}<strong>${esc(name(p))}</strong><span>${esc(p.floor===null?t('楼层由现场确认，未更新目录','Floor checked on site; directory unchanged'):floor(p))}</span></div><p>${esc(p.note[en?1:0])}</p><p class="small">${t('没有经核验的室内平面图，因此不提供“左转／右转”等逐步指令。','No verified indoor plan is available, so turn-by-turn indoor instructions are not supplied.')}</p><button id="completeGuide" class="primary full">${icon('check')}${t('已找到地点','I found the place')}</button><button id="guideIssue" class="outline full">${t('仍然找不到，记录问题','Still cannot find it · record an issue')}</button></div>`}`;
 $('#endGuide').onclick=()=>endGuide();$('#toggleAssist')?.addEventListener('click',()=>{if(state.watch!==null){stopWatch();renderGuide();toast(t('到楼位置提醒已停止。','Arrival location prompts stopped.'));}else $('#assistDialog').showModal();});$('#arrivedBuilding')?.addEventListener('click',()=>advanceBuilding('manual'));$('#floorChecked')?.addEventListener('click',()=>{state.stage=2;$('#arrivalPrompt').hidden=true;renderGuide();});$('#previousStage')?.addEventListener('click',()=>{state.stage=0;renderGuide();});$('#completeGuide')?.addEventListener('click',()=>{endGuide();toast(t('已完成地点查找。若信息有变化，可记录反馈。','Place found. Record feedback if anything has changed.'));});$('#guideIssue')?.addEventListener('click',()=>{$('#reportPlace').textContent=b.name+' · '+p.name;$('#reportDialog').showModal();});}
function endGuide(){stopWatch();state.snooze=0;state.guide=null;$('#arrivalPrompt').hidden=true;location.hash='/place/'+state.selected.id;render();}
function arrivalPrompt(reason){if(!state.guide||state.muted||Date.now()<state.snooze)return;state.promptReason=reason;const p=state.guide;$('#arrivalPrompt').hidden=false;$('#arrivalPrompt').innerHTML=`<div class="arrival-mark">${icon('pin')}</div><div><p class="eyebrow">${reason==='manual'?t('手动到楼确认','MANUAL BUILDING CHECK-IN'):t('接近目标建筑 · GPS 近似判断','NEAR THE BUILDING · GPS ESTIMATE')}</p><h2>${p.floor===null?t('先别按房间号猜楼层。','Check the floor before going upstairs.'):t('接下来，核对目标楼层。','Next, check the destination floor.')}</h2><p>${esc(p.floor===null?t('楼层待核实，请查看现场目录或询问工作人员。','The floor is unconfirmed. Use the directory or ask staff.'):name(p)+' · '+floor(p))}</p><div class="prompt-actions"><button id="promptContinue" class="primary">${t('查看楼层步骤','Show floor step')}</button><button id="promptSnooze" class="text-button">${t('稍后 5 分钟','Snooze 5 min')}</button><button id="promptMute" class="text-button">${t('本次不再提示','Mute this guidance')}</button></div></div>`;$('#promptContinue').onclick=()=>{state.stage=1;state.snooze=0;$('#arrivalPrompt').hidden=true;renderGuide();};$('#promptSnooze').onclick=()=>{state.snooze=Date.now()+300000;state.prompted=false;$('#arrivalPrompt').hidden=true;};$('#promptMute').onclick=()=>{state.muted=true;state.snooze=0;$('#arrivalPrompt').hidden=true;};}
function advanceBuilding(reason){state.stage=1;stopWatch();renderGuide();arrivalPrompt(reason);}
function toast(text){$('#notice').textContent=text;$('#notice').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#notice').hidden=true,6000);}
$('#search').oninput=e=>{state.query=e.target.value;render();};$('#searchForm').onsubmit=e=>{e.preventDefault();state.query=$('#search').value;render();};document.querySelectorAll('[data-category]').forEach(el=>el.onclick=()=>{state.category=el.dataset.category;if(state.category!=='toilet'){state.accessible=false;state.neutral=false;$('#accessible').checked=false;$('#neutral').checked=false;}render();});$('#accessible').onchange=e=>{state.accessible=e.target.checked;render();};$('#neutral').onchange=e=>{state.neutral=e.target.checked;render();};$('#changeOrigin').onclick=()=>{$('#locationError').textContent='';$('#locationDialog').showModal();};$('#useBuilding').onclick=()=>{state.origin={...buildings.find(b=>b.id===$('#originBuilding').value),mode:'building'};state.accuracy=0;$('#locationDialog').close();render();};$('#clearLocation').onclick=()=>{stopWatch();state.origin=null;state.accuracy=0;$('#locationDialog').close();render();};$('#mapPick').onclick=()=>{state.pick=!state.pick;renderMap();};$('#exampleRoom').onclick=()=>openPlace('library404');document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());
function acceptPosition(position){const p={lat:position.coords.latitude,lon:position.coords.longitude};if(!inCampus(p)){toast(t('当前位置不在主校园范围，已保留原参考起点。可改为手动选点。','Location is outside the main campus. The reference origin is unchanged; choose a point manually.'));return false;}state.origin={...p,mode:'gps',name:t('当前位置','Device location')};state.accuracy=position.coords.accuracy;render();if(state.accuracy>60)toast(t('定位误差较大，排序仅供参考；不会触发自动到楼提醒。','Location accuracy is low. Ranking is approximate; automatic arrival prompts will not trigger.'));return true;}
$('#useGPS').onclick=()=>{if(!navigator.geolocation){$('#locationError').textContent=t('浏览器不支持定位，请使用参考起点。','Geolocation is unavailable; choose a reference origin.');return;}$('#locationError').textContent=t('正在等待位置授权…','Waiting for location permission…');navigator.geolocation.getCurrentPosition(pos=>{if(acceptPosition(pos))$('#locationDialog').close();else $('#locationError').textContent=t('当前位置不在主校园范围。','Location is outside the main campus.');},()=>{$('#locationError').textContent=t('未能取得位置。可以继续使用建筑或地图参考起点。','Location unavailable. You can use a building or map reference point.');},{enableHighAccuracy:true,timeout:12000,maximumAge:30000});};
$('#consentAssist').onclick=()=>{if(!state.guide)return;$('#assistDialog').close();if(!navigator.geolocation){toast(t('定位不可用，请手动确认到楼。','Location unavailable; check in manually.'));return;}stopWatch();state.prompted=false;state.watch=navigator.geolocation.watchPosition(pos=>{if(!state.guide)return;const current={lat:pos.coords.latitude,lon:pos.coords.longitude};if(!inCampus(current)){stopWatch();toast(t('位置不在主校园范围，到楼提醒已停止。','Outside the main campus; arrival prompts stopped.'));renderGuide();return;}acceptPosition(pos);if(proximityHelp(current,bOf(state.guide),pos.coords.accuracy)&&!state.prompted&&!state.muted&&Date.now()>=state.snooze){state.prompted=true;arrivalPrompt('gps');}},()=>{stopWatch();toast(t('位置不可用，已停止位置提醒；仍可手动确认到楼。','Location unavailable; prompts stopped. Manual check-in remains available.'));if(state.guide)renderGuide();},{enableHighAccuracy:true,timeout:15000,maximumAge:15000});renderGuide();};$('#manualAssist').onclick=()=>{$('#assistDialog').close();stopWatch();renderGuide();};window.addEventListener('pagehide',stopWatch);
$('#downloadReport').onclick=()=>{const p=state.selected;if(!p)return;const note=$('#issueNote').value.trim();if(!note){$('#issueNote').focus();toast(t('请先填写现场观察。','Add an observation first.'));return;}const blob=new Blob([JSON.stringify({prototype:'Campus Find',place:p.id,building:p.building,type:$('#issueType').value,observation:note,createdAt:new Date().toISOString(),status:'local-note-not-submitted'},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='campus-find-feedback-'+p.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#reportDialog').close();toast(t('已生成本地反馈文件，尚未提交。','Local feedback file generated; nothing submitted.'));};
function renderAbout(){$('#about').innerHTML=`<p class="eyebrow">GREENGO / A NEW DIRECTION</p><h1>${t('从整段通勤，<br>聚焦最后一个小地点。','From the whole commute.<br>To the last little place.')}</h1><p class="about-intro">${t('专注伯明翰大学校园内的教室、楼层和附近厕所。先验证“找不到具体地点”的问题，再逐步扩大地点目录。','A focused prototype for rooms, floors and nearby toilets at the University of Birmingham. Investigate the difficulty of finding specific places before expanding the directory.')}</p><div class="about-grid"><article><span class="eyebrow">01 / CAN DO</span><h2>${t('可以直接体验','Ready to try')}</h2><p>${t('房间与建筑搜索、设施筛选、近似距离排序、拖动缩放地图、地点收藏、分阶段到楼／楼层／地点引导，以及本地反馈记录。','Search rooms and buildings, filter toilets, rank approximate distances, pan and zoom the map, save places, follow building–floor–place guidance and download feedback notes.')}</p></article><article><span class="eyebrow">02 / ARRIVAL ASSIST</span><h2>${t('主动，但由使用者控制','Proactive, with control')}</h2><p>${t('自愿开启页面内到楼位置提醒；接近建筑时主动提示核对楼层。可稍后处理、静音或停止；没有后台定位，也不会自动识别所在房间。手动到楼确认同样可体验该提醒。','Opt into in-page arrival prompts. Near the building, a floor-check suggestion appears. Snooze, mute or stop it. No background tracking or automatic room detection. Manual building check-in also demonstrates the prompt.')}</p></article><article><span class="eyebrow">03 / DATA HONESTY</span><h2>${t('未知的，就明确标注','Keep the unknowns visible')}</h2><p>${t('14 个地点只是试用目录，不覆盖全校。距离按近似建筑中心计算，不是室内路线或步行距离。公开来源不代表现场核验；未接入实时开放、占用、门禁、电梯故障或室内定位。','The 14-place pilot directory is not campus-wide. Distances use approximate building centres, not indoor routes or walking paths. Source-linked does not mean field-verified. No live opening, occupancy, door access, lift fault or indoor positioning feed.')}</p></article><article><span class="eyebrow">04 / PRIVACY</span><h2>${t('位置留在当前页面','Location stays in this page')}</h2><p>${t('不登录也能查找。收藏仅保存地点 ID 于本浏览器；位置不上传或持久保存。地图图片随网站加载，搜索和排序在本地运行；只有主动打开来源或官方地图时才访问相应网站。','No login required. Bookmarks store place IDs in this browser; location is not uploaded or persisted. The map image loads with the site, and search and ranking run locally. Source websites open only when their links are selected.')}</p></article></div><h2>${t('地点资料来源','Directory sources')}</h2><div class="source-list">${Object.values(sources).map(s=>`<a href="${s.url}" target="_blank" rel="noopener">${esc(s.name)} ↗</a>`).join('')}</div><p class="small">${t('公开资料查阅于','Public sources consulted')} ${checked} · ${t('建筑地图继承早期原型，未重新测绘。','The building map is retained from the earlier prototype, not resurveyed.')}</p><a class="outline" href="https://dawsen1208.github.io/greengo-uob-commute/" target="_blank" rel="noopener">${t('查看保留的 GreenGo 通勤原型','View the preserved GreenGo commute prototype')} ↗</a></section>`;}
function route(){const path=location.hash.replace(/^#\/?/,'').split('/'),page=path[0]||'find';if(page!=='guide'&&state.guide){stopWatch();state.guide=null;$('#arrivalPrompt').hidden=true;}if(page==='place'&&places.some(p=>p.id===path[1])){state.selected=places.find(p=>p.id===path[1]);}else if(page==='guide'&&places.some(p=>p.id===path[1])){state.selected=places.find(p=>p.id===path[1]);if(!state.guide){state.guide=state.selected;state.stage=0;}}else{state.selected=null;state.view=['saved','about'].includes(page)?page:'find';}const about=state.view==='about'&&!state.selected;$('#workspace').hidden=about;$('#about').hidden=!about;if(about)renderAbout();render();}
setInterval(()=>{if(state.snooze&&Date.now()>=state.snooze&&state.guide&&state.stage<2&&!state.muted){state.snooze=0;arrivalPrompt(state.promptReason||'manual');}},10000);
window.addEventListener('hashchange',route);route();
